const emptyCustomer=():Omit<Customer,"id">=>({createdAt:today(),name:"",phone:"",address:"",birthNumber:"",manager:"신홍규",coordinationManager:"신홍규",memo:"",contractDate:"",contractAmount:0,prepaidAmount:0,installmentMonths:0,lenderUnitPrice:0,lenderCount:0,isAccident:false});
function Customers(){
 const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [open,setOpen]=useState(false);const [editing,setEditing]=useState<Customer|null>(null);const [selectedId,setSelectedId]=useState<string|null>(null);const [form,setForm]=useState(emptyCustomer());const [del,setDel]=useState<Customer|null>(null);const [payOpen,setPayOpen]=useState(false);const [repayOpen,setRepayOpen]=useState(false);const [additionalOpen,setAdditionalOpen]=useState(false);const [recoveryOpen,setRecoveryOpen]=useState(false);const [calculatorOpen,setCalculatorOpen]=useState(false);const [salesCalculatorOpen,setSalesCalculatorOpen]=useState(false);const [noticeOpen,setNoticeOpen]=useState(false);const [eformOpen,setEformOpen]=useState(false);const [eformRefreshing,setEformRefreshing]=useState(false);
 const rows=useMemo(()=>s.customers.filter(c=>`${c.name} ${c.phone}`.toLowerCase().includes(q.toLowerCase())).sort(newestFirst),[s.customers,q]);const selected=s.customers.find(c=>c.id===selectedId)||null;
 function beginAdd(){setEditing(null);setForm(emptyCustomer());setOpen(true)}function beginEdit(c:Customer){setEditing(c);setForm({...c,contractAmount:c.baseContractAmount??c.contractAmount,prepaidAmount:c.basePrepaidAmount??c.prepaidAmount,lenderCount:c.baseLenderCount??c.lenderCount,manager:staffManager(c.manager),coordinationManager:staffManager(c.coordinationManager)});setOpen(true)}function save(){if(editing)s.updateCustomer(editing.id,form);else s.addCustomer(form);setOpen(false)}async function refreshEformStatus(customerId?:string){setEformRefreshing(true);try{const r=await fetch("/api/eformsign/status",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(customerId?{customerId}:{})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||"전자서명 상태 조회에 실패했습니다.");await s.refresh();if(j.failed){const firstError=Array.isArray(j.results)?j.results.find((x:any)=>!x.ok)?.error:"";alert(`전자서명 상태 ${j.updated||0}건 갱신, ${j.failed}건 조회 실패${firstError?`\n\n실패 원인: ${firstError}`:""}`);}else if(customerId)alert(j.updated?"전자서명 상태를 갱신했습니다.":"조회할 발송 문서가 없습니다.");}catch(e){alert(e instanceof Error?e.message:"전자서명 상태 조회에 실패했습니다.")}finally{setEformRefreshing(false)}}
 return <><PageHeader title="고객 관리" description="고객 기본정보와 계약정보, 수임료 분납 일정, 사채업체 상환 일정을 한 곳에서 관리합니다." action={<div className="flex flex-wrap gap-2"><Button variant="secondary" onClick={()=>setSalesCalculatorOpen(true)}><Calculator size={15}/>영업 계산기</Button><Button variant="secondary" disabled={eformRefreshing} onClick={()=>void refreshEformStatus()}><RefreshCw size={15} className={eformRefreshing?"animate-spin":""}/>{eformRefreshing?"서명상태 확인중":"서명상태 새로고침"}</Button><Button onClick={beginAdd}><Plus size={15}/>고객 등록</Button></div>}/><Card className="mb-4 p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1);setSelectedId(null)}}/></Card><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1200px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["등록일","고객명","연락처","영업 담당자","조율 담당자","계약금액","미수금","선납금","분납기간","업체당 단가","업체수","전자서명",""].map(h=><th key={h} className="px-4 py-3 font-medium">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page,10).map(c=><tr key={c.id} onClick={()=>setSelectedId(c.id)} className={`cursor-pointer border-t transition-colors ${c.isAccident?`border-red-100 hover:bg-red-100/60 ${selectedId===c.id?"bg-red-100/80":"bg-red-50/70"}`:`border-slate-100 hover:bg-blue-50/50 ${selectedId===c.id?"bg-blue-100/70":""}`}`}><td className="px-4 py-3">{c.createdAt}</td><td className="px-4 py-3 font-semibold"><div className="flex items-center gap-2"><span>{c.name}</span>{c.isAccident&&<Badge tone="red">사고자</Badge>}</div></td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3">{won(c.contractAmount)}</td><td className="px-4 py-3 font-semibold text-red-600">{won(customerOutstanding(s.payments,c))}</td><td className="px-4 py-3">{won(c.prepaidAmount)}</td><td className="px-4 py-3">{c.installmentMonths?`${c.installmentMonths}개월`:"-"}</td><td className="px-4 py-3">{won(c.lenderUnitPrice)}</td><td className="px-4 py-3">{c.lenderCount}</td><td className="px-4 py-3"><Badge tone={eformStatus(c.eformsignStatus).tone}>{eformStatus(c.eformsignStatus).label}</Badge></td><td className="px-4 py-3"><div className="flex justify-end gap-1"><Button variant="secondary" onClick={e=>{e.stopPropagation();beginEdit(c)}}>수정</Button><Button variant="danger" onClick={e=>{e.stopPropagation();setDel(c)}}><Trash2 size={14}/>삭제</Button></div></td></tr>)}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage} pageSize={10}/></Card>
 {selected&&<CustomerDetail customer={selected} onEdit={beginEdit} onPayments={()=>setPayOpen(true)} onRepayments={()=>setRepayOpen(true)} onNotice={()=>setNoticeOpen(true)} onAdditionalContracts={()=>setAdditionalOpen(true)} onRecoveries={()=>setRecoveryOpen(true)} onCalculator={()=>setCalculatorOpen(true)} onEform={()=>setEformOpen(true)} onRefreshEform={()=>void refreshEformStatus(selected.id)} eformRefreshing={eformRefreshing}/>}<CustomerModal open={open} form={form} setForm={setForm} editing={!!editing} onClose={()=>setOpen(false)} onSave={save}/>{selected&&<PaymentScheduleModal key={`pay-${selected.id}-${payOpen}`} open={payOpen} customer={selected} onClose={()=>setPayOpen(false)}/>} {selected&&<RepaymentScheduleModal key={`repay-${selected.id}-${repayOpen}`} open={repayOpen} customer={selected} onClose={()=>setRepayOpen(false)}/>} {selected&&<AdditionalContractsModal key={`additional-${selected.id}-${additionalOpen}`} open={additionalOpen} customer={selected} onClose={()=>setAdditionalOpen(false)}/>} {selected&&<RecoveriesModal key={`recovery-${selected.id}-${recoveryOpen}`} open={recoveryOpen} customer={selected} onClose={()=>setRecoveryOpen(false)}/>} {selected&&<CustomerCalculator key={`calculator-${selected.id}-${calculatorOpen}`} open={calculatorOpen} customer={selected} onClose={()=>setCalculatorOpen(false)}/>}<SalesCalculator open={salesCalculatorOpen} onClose={()=>setSalesCalculatorOpen(false)}/>{selected&&<ScheduleNoticeModal key={`notice-${selected.id}-${noticeOpen}`} open={noticeOpen} customer={selected} onClose={()=>setNoticeOpen(false)}/>} {selected&&<EformsignModal key={`eform-${selected.id}-${eformOpen}`} open={eformOpen} customer={selected} onClose={()=>setEformOpen(false)}/>}<ConfirmDelete open={!!del} name={del?.name||"고객"} label="고객 정보와 연결된 계약·입금·상환·추가계약·환수 데이터" onClose={()=>setDel(null)} onConfirm={()=>{if(del){s.deleteCustomer(del.id);if(selectedId===del.id)setSelectedId(null)}}}/></>
}
function CustomerDetail({customer:c,onEdit,onPayments,onRepayments,onNotice,onAdditionalContracts,onRecoveries,onCalculator,onEform,onRefreshEform,eformRefreshing}:{customer:Customer;onEdit:(c:Customer)=>void;onPayments:()=>void;onRepayments:()=>void;onNotice:()=>void;onAdditionalContracts:()=>void;onRecoveries:()=>void;onCalculator:()=>void;onEform:()=>void;onRefreshEform:()=>void;eformRefreshing:boolean}){const s=useAdminStore();const paid=customerPaid(s.payments,c.id);const outstanding=isEformSignedStatus(c.eformsignStatus)?Math.max(0,c.contractAmount-paid):0;const extraContracts=s.additionalContracts.filter(x=>x.customerId===c.id);const recoveries=s.recoveries.filter(x=>x.customerId===c.id);return <Card className={`mt-4 p-5 ${c.isAccident?"border-red-200 bg-red-50/20":""}`}><div className="flex flex-col justify-between gap-3 border-b border-slate-100 pb-4 xl:flex-row xl:items-center"><div><div className="flex items-center gap-2 text-lg font-bold"><span>{c.name} 고객 정보</span>{c.isAccident&&<Badge tone="red">사고자</Badge>}</div><div className="mt-1 text-sm text-slate-500">{c.phone} · 영업 {c.manager} · 조율 {c.coordinationManager}</div>{c.isAccident&&<div className="mt-2 text-xs font-semibold text-red-600">사고자 고객은 납부·상환 일정 및 일정 공지 대상에서 제외됩니다.</div>}</div><div className="flex flex-wrap gap-2"><Button variant="secondary" onClick={()=>onEdit(c)}>고객정보 수정</Button><Button disabled={c.isAccident} onClick={onPayments}>입금/분납관리</Button><Button variant="secondary" disabled={c.isAccident} onClick={onRepayments}>상환 일정 관리</Button><Button variant="secondary" disabled={c.isAccident} onClick={onNotice}>일정 공지 만들기</Button><Button variant="secondary" disabled={c.isAccident} onClick={onAdditionalContracts}>추가 계약</Button><Button variant="secondary" onClick={onRecoveries}>환수 등록</Button><Button variant="secondary" disabled={c.isAccident} onClick={onCalculator}>조율 계산기</Button><Button variant="secondary" disabled={eformRefreshing||!c.eformsignDocumentId} onClick={onRefreshEform}><RefreshCw size={15} className={eformRefreshing?"animate-spin":""}/>서명상태 확인</Button><Button onClick={onEform}><FileSignature size={15}/>이폼사인 계약서</Button></div></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{[["등록일",c.createdAt],["영업 담당자",c.manager],["조율 담당자",c.coordinationManager],["계약일",c.contractDate||"-"],["주소",c.address||"-"],["생년월일/주민번호",c.birthNumber||"-"],["계약금액",won(c.contractAmount)],["추가 계약",`${extraContracts.length}건 · ${won(extraContracts.reduce((a,b)=>a+b.contractAmount,0))}`],["선납금",won(c.prepaidAmount)],["분납기간",c.installmentMonths?`${c.installmentMonths}개월`:"-"],["업체당 단가",won(c.lenderUnitPrice)],["업체수",`${c.lenderCount}곳`],["계약대금 실입금",won(paid)],["미수금",won(outstanding)],["환수",`${recoveries.length}건 · ${won(recoveries.reduce((a,b)=>a+b.amount,0))}`],["상환 일정",`${s.repayments.filter(r=>r.customerId===c.id).length}건`],["전자서명",eformStatus(c.eformsignStatus).label]].map(([l,v])=><div key={l} className="rounded-xl bg-slate-50 p-4"><div className="text-xs font-semibold text-slate-500">{l}</div><div className="mt-1 font-bold">{v}</div></div>)}</div>{c.memo&&<div className="mt-4 rounded-xl border border-slate-100 p-4 text-sm"><div className="mb-1 text-xs font-semibold text-slate-500">메모</div>{c.memo}</div>}</Card>}
function CustomerModal({open,form,setForm,editing,onClose,onSave}:{open:boolean;form:Omit<Customer,"id">;setForm:(v:Omit<Customer,"id">)=>void;editing:boolean;onClose:()=>void;onSave:()=>void}){return <Modal open={open} title={editing?"고객정보 수정":"고객 등록"} onClose={onClose}><div className="grid gap-4 sm:grid-cols-2">{!editing&&<CustomerTextImport open={open} form={form} setForm={setForm}/>}<Label text="등록일"><input type="date" className={field} value={form.createdAt} onChange={e=>setForm({...form,createdAt:e.target.value})}/></Label><Label text="영업 담당자"><select className={field} value={form.manager} onChange={e=>setForm({...form,manager:e.target.value as Manager})}>{managerOptions(form.manager).map(m=><option key={m}>{m}</option>)}</select></Label><Label text="조율 담당자"><select className={field} value={form.coordinationManager} onChange={e=>setForm({...form,coordinationManager:e.target.value as Manager})}>{managerOptions(form.coordinationManager).map(m=><option key={m}>{m}</option>)}</select></Label><Label text="고객명"><input className={field} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Label><Label text="연락처"><input className={field} value={form.phone} onChange={e=>setForm({...form,phone:formatPhone(e.target.value)})} inputMode="numeric" placeholder="010-1234-5678"/></Label><Label text="주소"><input className={field} value={form.address} onChange={e=>setForm({...form,address:e.target.value})} placeholder="계약서에 입력할 주소"/></Label><Label text="생년월일/주민번호"><input className={field} value={form.birthNumber} onChange={e=>setForm({...form,birthNumber:formatBirthNumber(e.target.value)})} inputMode="numeric" placeholder="000000-0000000"/></Label><Label text="계약일"><input type="date" className={field} value={form.contractDate} onChange={e=>setForm({...form,contractDate:e.target.value})}/></Label><Label text="계약금액"><NumberInput value={form.contractAmount} onChange={v=>setForm({...form,contractAmount:v})}/></Label><Label text="선납금"><NumberInput value={form.prepaidAmount} onChange={v=>setForm({...form,prepaidAmount:v})}/></Label><Label text="분납기간(개월)"><NumberInput value={form.installmentMonths} onChange={v=>setForm({...form,installmentMonths:v})}/></Label><Label text="업체당 단가"><NumberInput value={form.lenderUnitPrice} onChange={v=>setForm({...form,lenderUnitPrice:v})}/></Label><Label text="업체수"><NumberInput value={form.lenderCount} onChange={v=>setForm({...form,lenderCount:v})}/></Label><label className="text-sm font-semibold">사고자<div className={`mt-1.5 flex min-h-10 items-center gap-3 rounded-lg border px-3 ${form.isAccident?"border-red-200 bg-red-50":"border-slate-200 bg-white"}`}><input type="checkbox" checked={!!form.isAccident} onChange={e=>setForm({...form,isAccident:e.target.checked})} className="h-4 w-4 accent-red-600"/><div><div className={form.isAccident?"font-bold text-red-700":"font-semibold text-slate-700"}>{form.isAccident?"사고자로 표시":"사고자 아님"}</div><div className="text-[11px] font-normal text-slate-400">체크 시 계약금액은 실제 납부액으로 자동 조정됩니다.</div></div></div></label><label className="sm:col-span-2 text-sm font-semibold">메모<textarea className={`${textarea} mt-1.5`} value={form.memo} onChange={e=>setForm({...form,memo:e.target.value})}/></label><div className="sm:col-span-2 flex justify-end gap-2"><Button variant="secondary" onClick={onClose}>취소</Button><Button onClick={onSave}>{editing?"수정 저장":"등록"}</Button></div></div></Modal>}

function EformsignModal({open,customer,onClose}:{open:boolean;customer:Customer;onClose:()=>void}){
 const s=useAdminStore();const [email,setEmail]=useState("");const [phone,setPhone]=useState(customer.phone);const [message,setMessage]=useState("계약서 확인 후 서명 부탁드립니다.");const [sending,setSending]=useState(false);
 useEffect(()=>{if(open){setPhone(customer.phone);setEmail("")}},[open,customer.id,customer.phone]);
 async function send(){if(!phone.trim()&&!email.trim())return alert("전화번호 또는 이메일을 입력해주세요.");if(!customer.contractDate)return alert("고객정보에 계약일을 먼저 입력해주세요.");setSending(true);try{const r=await fetch("/api/eformsign/send",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({customerId:customer.id,phone,email,message})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||"이폼사인 전송에 실패했습니다.");alert(`이폼사인 계약서를 전송했습니다.${j.documentId?`\n문서 ID: ${j.documentId}`:""}`);await s.refresh();onClose()}catch(e){alert(e instanceof Error?e.message:"이폼사인 전송에 실패했습니다.")}finally{setSending(false)}}
 return <Modal open={open} title={`${customer.name} · 이폼사인 계약서 전송`} onClose={onClose}><div className="space-y-4"><div className="rounded-xl bg-blue-50 p-4 text-sm text-blue-800"><b>{customer.name}</b> 고객의 계약정보를 템플릿에 자동 입력하고 서명 요청을 전송합니다.</div><div className="grid gap-4 sm:grid-cols-2"><Label text="고객명"><input className={field} value={customer.name} disabled/></Label><Label text="계약일"><input className={field} value={customer.contractDate||""} disabled/></Label><Label text="전화번호(SMS)"><input className={field} value={phone} onChange={e=>setPhone(formatPhone(e.target.value))} inputMode="numeric" placeholder="010-1234-5678"/></Label><Label text="이메일(선택)"><input type="email" className={field} value={email} onChange={e=>setEmail(e.target.value)} placeholder="customer@example.com"/></Label><Label text="계약금액"><input className={field} value={won(customer.contractAmount)} disabled/></Label><Label text="선납금"><input className={field} value={won(customer.prepaidAmount)} disabled/></Label><Label text="업체수"><input className={field} value={`${customer.lenderCount}곳`} disabled/></Label><Label text="업체당 단가"><input className={field} value={won(customer.lenderUnitPrice)} disabled/></Label></div><Label text="전송 메시지"><input className={field} value={message} onChange={e=>setMessage(e.target.value)}/></Label><div className="flex justify-end gap-2"><Button variant="secondary" onClick={onClose}>취소</Button><Button onClick={send} className={sending?"pointer-events-none opacity-60":""}><FileSignature size={15}/>{sending?"전송 중...":"계약서 전송"}</Button></div></div></Modal>
}

type PayDraft=CustomerPaymentRow;
type RepayDraft=CustomerRepaymentRow;
function PaymentScheduleModal({open,customer,onClose}:{open:boolean;customer:Customer;onClose:()=>void}){
 const s=useAdminStore();
 const makeRows=():PayDraft[]=>{const x=s.payments.filter(p=>p.customerId===customer.id&&p.scheduleType!=="환수"&&p.scheduleType!=="추가계약").sort((a,b)=>a.dueDate.localeCompare(b.dueDate)||((a.rescheduleSequence||0)-(b.rescheduleSequence||0))).map(({id,dueDate,dueAmount,paidDate,paidAmount,status,memo,paymentMethod,settlementMemo,scheduleType,rootScheduleId,rescheduledFromId,rescheduleSequence})=>({id,dueDate,dueAmount,paidDate,paidAmount,status,memo,paymentMethod:paymentMethod||"계좌이체",settlementMemo:settlementMemo||"",scheduleType,rootScheduleId,rescheduledFromId,rescheduleSequence}));return x.length?x:[{dueDate:today(),dueAmount:0,paidDate:"",paidAmount:0,status:"예정",memo:"",paymentMethod:"계좌이체",settlementMemo:"",scheduleType:"일반",rescheduleSequence:0}]};
 const [rows,setRows]=useState<PayDraft[]>(makeRows);const [reschedules,setReschedules]=useState<Record<string,{dueDate:string;dueAmount:number;memo:string}>>({});
 useEffect(()=>{if(open){setRows(makeRows());setReschedules({})}},[open,customer.id]);
 function update(i:number,p:Partial<PayDraft>){setRows(r=>r.map((x,n)=>n===i?{...x,...p}:x))}
 function addReschedule(r:PayDraft){const id=r.id;if(!id)return;setReschedules(x=>({...x,[id]:{dueDate:"",dueAmount:paymentRemaining(r as Payment),memo:"연체 후 재약정"}}))}
 async function save(){await s.setCustomerPayments(customer.id,rows);for(const [fromId,v] of Object.entries(reschedules)){const row=rows.find(r=>r.id===fromId);if(row?.status==="연체"&&v.dueDate)await s.createRescheduledPayment(fromId,v)}onClose()}
 return <Modal open={open} title={`${customer.name} · 입금/분납 일정`} onClose={onClose}><p className="mb-4 text-sm text-slate-500">연체 건은 기존 이력을 남긴 채 다음 납부 예정일을 재약정으로 연결합니다. 재약정 금액은 매출/예정금액에 중복 합산되지 않습니다.</p><div className="space-y-3">{rows.map((r,i)=>{const child=r.id?s.payments.find(p=>p.rescheduledFromId===r.id):undefined;const next=r.id?reschedules[r.id]:undefined;return <div key={r.id||i} className="rounded-xl border border-slate-200 bg-slate-50/50 p-4"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2"><b className="text-sm">납부 일정 {i+1}</b>{r.scheduleType==="재약정"&&<Badge tone="amber">재약정 {r.rescheduleSequence||1}차</Badge>}</div>{rows.length>1&&(child?<Badge tone="gray">이력보존</Badge>:<Button variant="danger" onClick={()=>setRows(x=>x.filter((_,n)=>n!==i))}>삭제</Button>)}</div><div className="grid gap-3 sm:grid-cols-2"><Label text="납부 예정일"><input type="date" className={field} value={r.dueDate} onChange={e=>update(i,{dueDate:e.target.value})}/></Label><Label text="예정금액"><NumberInput value={r.dueAmount} onChange={v=>update(i,{dueAmount:v})}/></Label><Label text="실제 입금일"><input type="date" className={field} value={r.paidDate} onChange={e=>update(i,{paidDate:e.target.value})}/></Label><Label text="실입금액"><NumberInput value={r.paidAmount} onChange={v=>update(i,{paidAmount:v})}/></Label><Label text="결제방법"><select className={field} value={r.paymentMethod||"계좌이체"} onChange={e=>update(i,{paymentMethod:e.target.value})}>{paymentMethods.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="상태"><select className={field} value={r.status} onChange={e=>update(i,{status:e.target.value as PaymentStatus})}>{paymentStatuses.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="메모"><input className={field} value={r.memo} onChange={e=>update(i,{memo:e.target.value})}/></Label></div>{r.status==="연체"&&r.id&&<div className="mt-4 border-t border-red-100 pt-4">{child?<div className="rounded-lg bg-amber-50 px-3 py-2 text-sm text-amber-800"><b>다음 납부 예정일 등록됨</b> · {child.dueDate} · {won(child.dueAmount)}</div>:next?<div className="grid gap-3 rounded-xl border border-amber-200 bg-amber-50/60 p-3 sm:grid-cols-2"><Label text="다음 납부 예정일"><input type="date" className={field} value={next.dueDate} onChange={e=>setReschedules(x=>({...x,[r.id!]:{...next,dueDate:e.target.value}}))}/></Label><Label text="재약정 예정금액"><NumberInput value={next.dueAmount} onChange={v=>setReschedules(x=>({...x,[r.id!]:{...next,dueAmount:v}}))}/></Label><div className="sm:col-span-2"><Label text="재약정 메모"><input className={field} value={next.memo} onChange={e=>setReschedules(x=>({...x,[r.id!]:{...next,memo:e.target.value}}))}/></Label></div></div>:<Button variant="secondary" onClick={()=>addReschedule(r)}><Plus size={14}/>다음 납부 예정일 추가</Button>}</div>}</div>})}</div><button onClick={()=>setRows(x=>[...x,{dueDate:"",dueAmount:0,paidDate:"",paidAmount:0,status:"예정",memo:"",paymentMethod:"계좌이체",settlementMemo:"",scheduleType:"일반",rescheduleSequence:0}])} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-blue-300 py-3 text-sm font-semibold text-blue-700 hover:bg-blue-50"><Plus size={15}/>납부 일정 추가</button><div className="mt-5 flex justify-end gap-2"><Button variant="secondary" onClick={onClose}>취소</Button><Button onClick={save}>일정 저장</Button></div></Modal>
}
function RepaymentScheduleModal({open,customer,onClose}:{open:boolean;customer:Customer;onClose:()=>void}){const s=useAdminStore();const makeRows=()=>{const x=s.repayments.filter(r=>r.customerId===customer.id).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(({id,lenderName,contactType,contactValue,dueDate,amount,account,status,memo})=>({id,lenderName,contactType,contactValue,dueDate,amount,account,status,memo}));return x.length?x:[{lenderName:"",contactType:"번호" as ContactType,contactValue:"",dueDate:today(),amount:0,account:"",status:"예정" as RepaymentStatus,memo:""}]};const [rows,setRows]=useState<RepayDraft[]>(makeRows);useEffect(()=>{if(open)setRows(makeRows())},[open,customer.id]);function update(i:number,p:Partial<RepayDraft>){setRows(r=>r.map((x,n)=>n===i?{...x,...p}:x))}async function save(){await s.setCustomerRepayments(customer.id,rows);onClose()}return <Modal open={open} title={`${customer.name} · 상환 일정`} onClose={onClose}><p className="mb-4 text-sm text-slate-500">업체명만 입력해도 우선 저장할 수 있습니다. 연락수단·연락처·상환일·금액·계좌정보는 공란으로 저장한 뒤 나중에 보완할 수 있습니다.</p><div className="space-y-3">{rows.map((r,i)=><div key={i} className="rounded-xl border border-slate-200 bg-slate-50/50 p-4"><div className="mb-3 flex items-center justify-between"><b className="text-sm">업체 상환 {i+1}</b>{rows.length>1&&<Button variant="danger" onClick={()=>setRows(x=>x.filter((_,n)=>n!==i))}>삭제</Button>}</div><div className="grid gap-3 sm:grid-cols-2"><Label text="업체명"><input className={field} value={r.lenderName} onChange={e=>update(i,{lenderName:e.target.value})}/></Label><Label text="연락수단"><select className={field} value={r.contactType} onChange={e=>update(i,{contactType:e.target.value as ContactType})}><option value="">미확인 / 나중에 입력</option>{contactTypes.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="번호 또는 SNS 아이디"><input className={field} value={r.contactValue} onChange={e=>update(i,{contactValue:r.contactType==="번호"?formatPhone(e.target.value):e.target.value})} placeholder={r.contactType==="번호"?"010-1234-5678":"카카오톡/라인/텔레그램 ID"}/></Label><Label text="상환일"><input type="date" className={field} value={r.dueDate} onChange={e=>update(i,{dueDate:e.target.value})}/></Label><Label text="상환금액"><NumberInput value={r.status==="종결"?0:r.amount} disabled={r.status==="종결"} onChange={v=>update(i,{amount:v})}/></Label><Label text="업체 입금계좌 / 전달정보"><input className={field} value={r.account} onChange={e=>update(i,{account:e.target.value})} placeholder="상환일 당일 계좌 기록 가능"/></Label><Label text="상태"><select className={field} value={r.status} onChange={e=>{const status=e.target.value as RepaymentStatus;update(i,status==="종결"?{status,amount:0}:{status})}}>{repaymentStatuses.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="메모"><input className={field} value={r.memo} onChange={e=>update(i,{memo:e.target.value})}/></Label></div></div>)}</div><button onClick={()=>setRows(x=>[...x,{lenderName:"",contactType:"번호",contactValue:"",dueDate:"",amount:0,account:"",status:"예정",memo:""}])} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-amber-300 py-3 text-sm font-semibold text-amber-700 hover:bg-amber-50"><Plus size={15}/>업체 상환 일정 추가</button><div className="mt-5 flex justify-end gap-2"><Button variant="secondary" onClick={onClose}>취소</Button><Button onClick={save}>일정 저장</Button></div></Modal>}

function Contracts(){const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [statusView,setStatusView]=useState<"진행"|"종결">("진행");const contractRows=useMemo(()=>s.customers.filter(c=>c.contractAmount>0&&`${c.name} ${c.phone}`.toLowerCase().includes(q.toLowerCase())).map(c=>{const paid=customerPaid(s.payments,c.id);const status: "진행"|"종결"=paid>=c.contractAmount?"종결":"진행";return{c,paid,status}}).sort((a,b)=>newestFirst(a.c,b.c)),[s.customers,s.payments,q]);const counts=useMemo(()=>({진행:contractRows.filter(x=>x.status==="진행").length,종결:contractRows.filter(x=>x.status==="종결").length}),[contractRows]);const rows=useMemo(()=>contractRows.filter(x=>x.status===statusView),[contractRows,statusView]);return <><PageHeader title="계약 관리" description="고객관리의 계약정보를 자동으로 불러오며 납부액이 계약금액에 도달하면 종결로 표시됩니다."/><Card className="mb-4 space-y-3 p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1);setStatusView("진행")}}/><StatusTabs value={statusView} onChange={v=>{setStatusView(v);setPage(1)}} left={{value:"진행",label:"진행"}} right={{value:"종결",label:"종결"}} leftCount={counts.진행} rightCount={counts.종결}/></Card><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1000px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["계약일","고객명","연락처","영업 담당자","조율 담당자","계약금액","미수금","납부액","분납기간","상태"].map(h=><th key={h} className="px-4 py-3 font-medium">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(({c,paid,status})=>{const due=isEformSignedStatus(c.eformsignStatus)?Math.max(0,c.contractAmount-paid):0;return <tr key={c.id} className="border-t border-slate-100"><td className="px-4 py-3">{c.contractDate||c.createdAt}</td><td className="px-4 py-3 font-semibold">{c.name}</td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3">{won(c.contractAmount)}</td><td className="px-4 py-3 text-red-600">{won(due)}</td><td className="px-4 py-3 font-semibold text-blue-700">{won(paid)}</td><td className="px-4 py-3">{c.installmentMonths?`${c.installmentMonths}개월`:"-"}</td><td className="px-4 py-3"><Badge tone={status==="종결"?"green":"blue"}>{status}</Badge></td></tr>})}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card></>}
function CustomerPicker({open,onClose,onSelect}:{open:boolean;onClose:()=>void;onSelect:(c:Customer)=>void}){const s=useAdminStore();const [q,setQ]=useState("");const [page,setPage]=useState(1);const rows=useMemo(()=>s.customers.filter(c=>!c.isAccident&&`${c.name} ${c.phone}`.toLowerCase().includes(q.trim().toLowerCase())).sort(newestFirst),[s.customers,q]);if(!open)return null;function choose(c:Customer){onSelect(c);onClose()}return <div data-admin-edit-lock="true" className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/45 p-2 sm:p-4" onMouseDown={onClose}><div className="max-h-[calc(100dvh-16px)] w-full max-w-4xl overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-2xl sm:max-h-[90vh] sm:rounded-2xl" onMouseDown={e=>e.stopPropagation()}><div className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-100 bg-white px-5 py-4"><div><h2 className="font-bold">고객 선택</h2><p className="mt-1 text-xs text-slate-500">고객 행 또는 선택 버튼을 누르면 입금 일정에 바로 연결됩니다.</p></div><button onClick={onClose} className="rounded-lg px-2 py-1 text-slate-400 hover:bg-slate-100">✕</button></div><div className="p-5"><div className="mb-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1)}} placeholder="고객명 또는 전화번호 일부 입력"/></div><div className="overflow-x-auto rounded-xl border border-slate-200"><table className="admin-responsive-table w-full min-w-[820px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["등록일","고객명","연락처","영업 담당자","조율 담당자","계약금액","미수금",""].map(h=><th className="px-3 py-2.5" key={h}>{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(c=><tr key={c.id} onDoubleClick={()=>choose(c)} className="cursor-pointer border-t border-slate-100 transition hover:bg-blue-50/70"><td className="px-3 py-2.5">{c.createdAt}</td><td className="px-3 py-2.5 font-semibold"><CustomerNameCell customers={s.customers} customer={c}/></td><td className="px-3 py-2.5">{c.phone}</td><td className="px-3 py-2.5">{c.manager}</td><td className="px-3 py-2.5">{c.coordinationManager}</td><td className="px-3 py-2.5">{won(c.contractAmount)}</td><td className="px-3 py-2.5 font-semibold text-red-600">{won(customerOutstanding(s.payments,c))}</td><td className="px-3 py-2.5 text-right"><Button onClick={e=>{e.preventDefault();e.stopPropagation();choose(c)}}>선택</Button></td></tr>)}{rows.length===0&&<tr><td colSpan={8} className="px-4 py-10 text-center text-slate-400">검색 결과가 없습니다.</td></tr>}</tbody></table><Pagination page={page} total={rows.length} onChange={setPage}/></div></div></div></div>}
function Payments(){
 const s=useAdminStore();
 const [page,setPage]=useState(1);const [q,setQ]=useState("");const [statusView,setStatusView]=useState<"예정"|"완료">("예정");const [open,setOpen]=useState(false);const [picker,setPicker]=useState(false);const [editing,setEditing]=useState<Payment|null>(null);const [form,setForm]=useState(emptyPayment());const [newRows,setNewRows]=useState<NewPaymentRow[]>([emptyNewPaymentRow()]);const [del,setDel]=useState<Payment|null>(null);const [reschedule,setReschedule]=useState<{dueDate:string;dueAmount:number;memo:string}|null>(null);
 const paymentSearchRows=useMemo(()=>s.payments.filter(p=>{const c=s.customers.find(x=>x.id===p.customerId);return !c?.isAccident&&`${c?.name||""} ${c?.phone||""}`.toLowerCase().includes(q.toLowerCase())}).sort((a,b)=>(b.dueDate||"").localeCompare(a.dueDate||"")||newestFirst(a,b)),[s.payments,s.customers,q]);
 const paymentCounts=useMemo(()=>({예정:paymentSearchRows.filter(p=>p.status!=="완료"&&p.status!=="환불").length,완료:paymentSearchRows.filter(p=>p.status==="완료").length}),[paymentSearchRows]);
 const rows=useMemo(()=>paymentSearchRows.filter(p=>statusView==="완료"?p.status==="완료":p.status!=="완료"&&p.status!=="환불"),[paymentSearchRows,statusView]);
 const originalSchedules=useMemo(()=>originalPlannedPayments(s.payments).filter(p=>p.status!=="환불"&&!s.customers.find(c=>c.id===p.customerId)?.isAccident),[s.payments,s.customers]);
 const missingScheduleCustomers=useMemo(()=>s.customers.filter(c=>{if(c.isAccident||!isEformSignedStatus(c.eformsignStatus)||c.installmentMonths<=0||c.contractAmount<=0)return false;const scheduledTotal=originalSchedules.filter(p=>p.customerId===c.id).reduce((sum,p)=>sum+(p.dueAmount||0),0);return scheduledTotal<c.contractAmount}).sort(newestFirst),[s.customers,originalSchedules]);
 const selected=s.customers.find(c=>c.id===form.customerId);
 const existingNext=editing?s.payments.find(p=>p.rescheduledFromId===editing.id):undefined;
 function addForCustomer(customer:Customer){if(customer.isAccident)return alert("사고자 고객은 입금/분납 일정 대상에서 제외됩니다.");setEditing(null);setReschedule(null);setForm({...emptyPayment(),customerId:customer.id});setNewRows([emptyNewPaymentRow()]);setOpen(true)}
 function add(){setEditing(null);setReschedule(null);const search=q.trim().toLowerCase();const matches=search?s.customers.filter(c=>!c.isAccident&&`${c.name} ${c.phone}`.toLowerCase().includes(search)):[];const exact=search?matches.filter(c=>c.name.toLowerCase()===search||c.phone.toLowerCase()===search):[];const customer=exact.length===1?exact[0]:matches.length===1?matches[0]:null;if(customer){addForCustomer(customer);return}setForm({...emptyPayment(),customerId:""});setNewRows([emptyNewPaymentRow()]);setOpen(true)}
 function edit(p:Payment){if(p.scheduleType==="환수")return alert("환수 건은 고객정보의 [환수 등록]에서 수정해주세요.");if(p.scheduleType==="추가계약")return alert("추가 계약 선납금은 고객정보의 [추가 계약]에서 수정해주세요.");setEditing(p);setReschedule(null);setForm({...p,paymentMethod:p.paymentMethod||"계좌이체",settlementMemo:p.settlementMemo||""});setOpen(true)}
 function updateNewRow(i:number,p:Partial<NewPaymentRow>){setNewRows(r=>r.map((x,n)=>n===i?{...x,...p}:x))}
 function beginReschedule(){if(!editing)return;setReschedule({dueDate:"",dueAmount:paymentRemaining(form as Payment),memo:"연체 후 재약정"})}
 async function save(){if(!form.customerId)return alert("고객을 선택해주세요.");if(editing){if(form.status==="연체"&&reschedule&&!reschedule.dueDate)return alert("다음 납부 예정일을 선택해주세요.");await s.updatePayment(editing.id,form);if(form.status==="연체"&&reschedule?.dueDate)await s.createRescheduledPayment(editing.id,reschedule);setOpen(false);return}if(newRows.some(r=>!r.dueDate||r.dueAmount<0))return alert("납부 예정일과 금액을 확인해주세요.");await s.addPayments(newRows.map(r=>({...r,customerId:form.customerId,scheduleType:"일반",rescheduleSequence:0})));setOpen(false)}
 return <><PageHeader title="입금/분납 관리" description="수임료 예정·분납·실입금 데이터를 등록하고 수정 할 수 있습니다" action={<Button onClick={add}><Plus size={15}/>입금 일정 추가</Button>}/><Card className="mb-4 space-y-3 p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1);setStatusView("예정")}}/><StatusTabs value={statusView} onChange={v=>{setStatusView(v);setPage(1)}} left={{value:"예정",label:"예정"}} right={{value:"완료",label:"완료"}} leftCount={paymentCounts.예정} rightCount={paymentCounts.완료}/></Card>
 {missingScheduleCustomers.length>0&&<Card className="mb-4 overflow-hidden border border-amber-200"><div className="flex flex-col gap-2 border-b border-amber-100 bg-amber-50 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2 font-bold text-amber-900"><Badge tone="amber">분납 예정일 미등록</Badge><span>{missingScheduleCustomers.length}명</span></div><div className="mt-1 text-xs text-amber-700">재약정 일정은 기존 채권의 날짜 이동이므로 계약금액 대비 최초 등록 예정합계에는 중복 계산하지 않습니다.</div></div></div><div className="max-h-72 overflow-auto"><table className="admin-responsive-table w-full min-w-[900px] text-sm"><thead className="bg-amber-50/50 text-left text-xs text-slate-500"><tr>{["고객명","연락처","영업 담당자","조율 담당자","총 계약금액","미수금","등록 예정합계","미등록 예정금액",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{missingScheduleCustomers.map(c=>{const scheduledTotal=originalSchedules.filter(p=>p.customerId===c.id).reduce((sum,p)=>sum+(p.dueAmount||0),0);const missingAmount=Math.max(0,c.contractAmount-scheduledTotal);return <tr key={c.id} className="border-t border-amber-100"><td className="px-4 py-3 font-semibold"><CustomerNameCell customers={s.customers} customer={c}/></td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3">{won(c.contractAmount)}</td><td className="px-4 py-3 font-semibold text-red-600">{won(customerOutstanding(s.payments,c))}</td><td className="px-4 py-3">{won(scheduledTotal)}</td><td className="px-4 py-3 font-semibold text-red-600">{won(missingAmount)}</td><td className="px-4 py-3 text-right"><Button onClick={()=>addForCustomer(c)}><Plus size={14}/>일정 추가</Button></td></tr>})}</tbody></table></div></Card>}
 <Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1580px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["예정일","고객명","연락처","영업 담당자","조율 담당자","계약금액","미수금","예정금액","입금일","실입금액","결제방법","구분","상태","메모",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(p=>{const c=s.customers.find(x=>x.id===p.customerId);const child=s.payments.some(x=>x.rescheduledFromId===p.id);return <tr key={p.id} className="border-t border-slate-100"><td className="px-4 py-3">{p.dueDate}</td><td className="px-4 py-3 font-semibold"><CustomerNameCell customers={s.customers} customer={c}/></td><td className="px-4 py-3">{c?.phone||"-"}</td><td className="px-4 py-3">{c?.manager||"-"}</td><td className="px-4 py-3">{c?.coordinationManager||"-"}</td><td className="px-4 py-3 font-semibold">{c?won(c.contractAmount):"-"}</td><td className="px-4 py-3 font-semibold text-red-600">{c?won(customerOutstanding(s.payments,c)):"-"}</td><td className="px-4 py-3">{won(p.dueAmount)}</td><td className="px-4 py-3">{p.paidDate||"-"}</td><td className="px-4 py-3 text-blue-700">{won(p.paidAmount)}</td><td className="px-4 py-3">{p.paymentMethod||"계좌이체"}</td><td className="px-4 py-3">{p.scheduleType==="재약정"?<Badge tone="amber">재약정 {p.rescheduleSequence||1}차</Badge>:p.scheduleType==="환수"?<Badge tone="green">환수</Badge>:p.scheduleType==="추가계약"?<Badge tone="blue">추가계약 선납</Badge>:<Badge tone="gray">일반</Badge>}</td><td className="px-4 py-3"><Badge tone={p.status==="완료"?"green":p.status==="연체"||p.status==="미납"?"red":"blue"}>{p.status}</Badge></td><td className="max-w-48 truncate px-4 py-3">{p.memo||"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>edit(p)}>수정</Button>{p.scheduleType==="환수"||p.scheduleType==="추가계약"?<Badge tone="gray">전용 화면에서 관리</Badge>:child?<Badge tone="gray">이력보존</Badge>:<Button variant="danger" onClick={()=>setDel(p)}>삭제</Button>}</div></td></tr>})}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card>
 <Modal open={open} title={editing?"입금 일정 수정":"입금 일정 추가"} onClose={()=>setOpen(false)}><div className="mb-4"><Label text="고객"><button className={`${field} flex items-center justify-between text-left`} onClick={()=>setPicker(true)}>{selected?<span><b>{selected.name}</b> · {selected.phone}</span>:<span className="text-slate-400">고객 선택</span>}<UserRoundSearch size={16}/></button></Label></div>{editing?<><div className="grid gap-4 sm:grid-cols-2"><Label text="예정일"><input type="date" className={field} value={form.dueDate} onChange={e=>setForm({...form,dueDate:e.target.value})}/></Label><Label text="예정금액"><NumberInput value={form.dueAmount} onChange={v=>setForm({...form,dueAmount:v})}/></Label><Label text="입금일"><input type="date" className={field} value={form.paidDate} onChange={e=>setForm({...form,paidDate:e.target.value})}/></Label><Label text="실입금액"><NumberInput value={form.paidAmount} onChange={v=>setForm({...form,paidAmount:v})}/></Label><Label text="결제방법"><select className={field} value={form.paymentMethod||"계좌이체"} onChange={e=>setForm({...form,paymentMethod:e.target.value})}>{paymentMethods.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="상태"><select className={field} value={form.status} onChange={e=>setForm({...form,status:e.target.value as PaymentStatus})}>{paymentStatuses.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="메모"><input className={field} value={form.memo} onChange={e=>setForm({...form,memo:e.target.value})}/></Label></div>{form.status==="연체"&&<div className="mt-5 border-t border-red-100 pt-4"><div className="mb-2 text-sm font-bold text-red-700">연체 후 납부일정</div>{existingNext?<div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><b>다음 납부 예정일이 이미 연결되어 있습니다.</b><div className="mt-1">{existingNext.dueDate} · {won(existingNext.dueAmount)} · 재약정 {existingNext.rescheduleSequence||1}차</div></div>:reschedule?<div className="grid gap-3 rounded-xl border border-amber-200 bg-amber-50/60 p-4 sm:grid-cols-2"><Label text="다음 납부 예정일"><input type="date" className={field} value={reschedule.dueDate} onChange={e=>setReschedule({...reschedule,dueDate:e.target.value})}/></Label><Label text="재약정 예정금액"><NumberInput value={reschedule.dueAmount} onChange={v=>setReschedule({...reschedule,dueAmount:v})}/></Label><div className="sm:col-span-2"><Label text="메모"><input className={field} value={reschedule.memo} onChange={e=>setReschedule({...reschedule,memo:e.target.value})}/></Label></div><div className="sm:col-span-2 text-xs text-amber-700">기본금액은 기존 예정금액에서 이미 받은 금액을 뺀 잔액입니다. 기존 연체건은 이력으로 남고 새 일정만 현재 받을 예정금액에 반영됩니다.</div></div>:<Button variant="secondary" onClick={beginReschedule}><Plus size={14}/>다음 납부 예정일 추가</Button>}</div>}</>:<><p className="mb-3 text-sm text-slate-500">분납 일정이 여러 건이면 아래에서 일정을 추가한 뒤 한 번에 저장할 수 있습니다.</p><div className="space-y-3">{newRows.map((r,i)=><div key={i} className="rounded-xl border border-slate-200 bg-slate-50/50 p-4"><div className="mb-3 flex items-center justify-between"><b className="text-sm">납부 일정 {i+1}</b>{newRows.length>1&&<Button variant="danger" onClick={()=>setNewRows(x=>x.filter((_,n)=>n!==i))}>삭제</Button>}</div><div className="grid gap-3 sm:grid-cols-2"><Label text="예정일"><input type="date" className={field} value={r.dueDate} onChange={e=>updateNewRow(i,{dueDate:e.target.value})}/></Label><Label text="예정금액"><NumberInput value={r.dueAmount} onChange={v=>updateNewRow(i,{dueAmount:v})}/></Label><Label text="입금일"><input type="date" className={field} value={r.paidDate} onChange={e=>updateNewRow(i,{paidDate:e.target.value})}/></Label><Label text="실입금액"><NumberInput value={r.paidAmount} onChange={v=>updateNewRow(i,{paidAmount:v})}/></Label><Label text="결제방법"><select className={field} value={r.paymentMethod||"계좌이체"} onChange={e=>updateNewRow(i,{paymentMethod:e.target.value})}>{paymentMethods.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="상태"><select className={field} value={r.status} onChange={e=>updateNewRow(i,{status:e.target.value as PaymentStatus})}>{paymentStatuses.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="메모"><input className={field} value={r.memo} onChange={e=>updateNewRow(i,{memo:e.target.value})}/></Label></div></div>)}</div><button onClick={()=>setNewRows(x=>[...x,{...emptyNewPaymentRow(),dueDate:""}])} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-blue-300 py-3 text-sm font-semibold text-blue-700 hover:bg-blue-50"><Plus size={15}/>납부 일정 추가</button></>}<div className="mt-5 flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>취소</Button><Button onClick={save}>{editing?"저장":"일정 한번에 저장"}</Button></div></Modal><CustomerPicker open={picker} onClose={()=>setPicker(false)} onSelect={c=>setForm(f=>({...f,customerId:c.id}))}/><ConfirmDelete open={!!del} name={del?`${s.customers.find(c=>c.id===del.customerId)?.name||"고객"}님의 ${del.dueDate} 입금 일정`:"입금 일정"} label="입금 일정" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deletePayment(del.id)}}/></>
}
function Repayments(){const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [statusView,setStatusView]=useState<"예정"|"상환완료">("예정");const [editing,setEditing]=useState<Repayment|null>(null);const [del,setDel]=useState<Repayment|null>(null);const [scheduleCustomer,setScheduleCustomer]=useState<Customer|null>(null);const repaymentSearchRows=useMemo(()=>s.repayments.filter(r=>{const c=s.customers.find(x=>x.id===r.customerId);return !c?.isAccident&&`${c?.name||""} ${c?.phone||""} ${r.lenderName} ${r.contactValue}`.toLowerCase().includes(q.toLowerCase())}).sort((a,b)=>(b.dueDate||"").localeCompare(a.dueDate||"")||newestFirst(a,b)),[s.repayments,s.customers,q]);const repaymentCounts=useMemo(()=>({예정:repaymentSearchRows.filter(r=>r.status!=="상환완료"&&r.status!=="종결").length,상환완료:repaymentSearchRows.filter(r=>r.status==="상환완료"||r.status==="종결").length}),[repaymentSearchRows]);const rows=useMemo(()=>repaymentSearchRows.filter(r=>statusView==="상환완료"?r.status==="상환완료"||r.status==="종결":r.status!=="상환완료"&&r.status!=="종결"),[repaymentSearchRows,statusView]);const missingRepaymentCustomers=useMemo(()=>s.customers.filter(c=>!c.isAccident).map(c=>{const registeredCount=s.repayments.filter(r=>r.customerId===c.id).length;const remainingCount=Math.max(0,(c.lenderCount||0)-registeredCount);return{customer:c,registeredCount,remainingCount}}).filter(x=>x.customer.lenderCount>0&&x.remainingCount>0).sort((a,b)=>newestFirst(a.customer,b.customer)),[s.customers,s.repayments]);const totalRemainingLenders=useMemo(()=>missingRepaymentCustomers.reduce((sum,x)=>sum+x.remainingCount,0),[missingRepaymentCustomers]);return <><PageHeader title="상환 일정 관리" description="의뢰인이 사채업체에 상환해야 할 날짜·금액과 업체 연락정보를 관리합니다."/><Card className="mb-4 space-y-3 p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1);setStatusView("예정")}} placeholder="고객명, 전화번호, 업체명 또는 업체 연락정보 검색"/><StatusTabs value={statusView} onChange={v=>{setStatusView(v);setPage(1)}} left={{value:"예정",label:"예정"}} right={{value:"상환완료",label:"상환완료"}} leftCount={repaymentCounts.예정} rightCount={repaymentCounts.상환완료}/></Card>{missingRepaymentCustomers.length>0&&<Card className="mb-4 overflow-hidden border border-amber-200"><div className="flex flex-col gap-2 border-b border-amber-100 bg-amber-50 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2 font-bold text-amber-900"><Badge tone="amber">상환일정 미등록</Badge><span>{missingRepaymentCustomers.length}명</span><span className="text-sm font-semibold text-amber-700">· 총 {totalRemainingLenders}개 업체 등록 예정</span></div><div className="mt-1 text-xs text-amber-700">고객정보의 업체수보다 등록된 상환일정 수가 적은 고객만 표시합니다. 모든 업체의 상환일정을 등록하면 자동으로 목록에서 제외됩니다.</div></div></div><div className="max-h-72 overflow-auto"><table className="admin-responsive-table w-full min-w-[980px] text-sm"><thead className="bg-amber-50/50 text-left text-xs text-slate-500"><tr>{["고객명","연락처","영업 담당자","조율 담당자","고객정보 업체수","등록된 상환일정","등록 예정 업체수",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{missingRepaymentCustomers.map(({customer:c,registeredCount,remainingCount})=><tr key={c.id} className="border-t border-amber-100"><td className="px-4 py-3 font-semibold"><CustomerNameCell customers={s.customers} customer={c}/></td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3">{c.lenderCount}개</td><td className="px-4 py-3">{registeredCount}개</td><td className="px-4 py-3 font-bold text-red-600">{remainingCount}개</td><td className="px-4 py-3 text-right"><Button onClick={()=>setScheduleCustomer(c)}><Plus size={14}/>상환일정 추가</Button></td></tr>)}</tbody></table></div></Card>}<Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1280px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["상환일","고객명","연락처","영업 담당자","조율 담당자","업체명","업체 연락수단","업체 연락정보","상환금액","계좌/전달정보","상태","메모",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(r=>{const c=s.customers.find(x=>x.id===r.customerId);return <tr key={r.id} className="border-t border-slate-100"><td className="px-4 py-3">{r.dueDate}</td><td className="px-4 py-3 font-semibold"><CustomerNameCell customers={s.customers} customer={c}/></td><td className="px-4 py-3">{c?.phone||"-"}</td><td className="px-4 py-3">{c?.manager||"-"}</td><td className="px-4 py-3">{c?.coordinationManager||"-"}</td><td className="px-4 py-3 font-semibold">{r.lenderName}</td><td className="px-4 py-3">{r.contactType||"-"}</td><td className="px-4 py-3">{r.contactValue||"-"}</td><td className="px-4 py-3">{won(r.amount)}</td><td className="max-w-56 truncate px-4 py-3">{r.account||"-"}</td><td className="px-4 py-3"><Badge tone={r.status==="상환완료"||r.status==="종결"?"green":r.status==="연체"||r.status==="추심"?"red":"amber"}>{r.status}</Badge></td><td className="max-w-44 truncate px-4 py-3">{r.memo||"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>setEditing(r)}>수정</Button><Button variant="danger" onClick={()=>setDel(r)}>삭제</Button></div></td></tr>})}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card>{scheduleCustomer&&<RepaymentScheduleModal open customer={scheduleCustomer} onClose={()=>setScheduleCustomer(null)}/>} {editing&&<RepaymentEdit repayment={editing} onClose={()=>setEditing(null)}/>}<ConfirmDelete open={!!del} name={del?`${s.customers.find(c=>c.id===del.customerId)?.name||"고객"}님의 ${del.lenderName} 상환 일정`:"상환 일정"} label="상환 일정" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deleteRepayment(del.id)}}/></>}
function RepaymentEdit({repayment,onClose}:{repayment:Repayment;onClose:()=>void}){const s=useAdminStore();const [f,setF]=useState({...repayment});return <Modal open title="상환 일정 수정" onClose={onClose}><div className="grid gap-4 sm:grid-cols-2"><Label text="업체명"><input className={field} value={f.lenderName} onChange={e=>setF({...f,lenderName:e.target.value})}/></Label><Label text="연락수단"><select className={field} value={f.contactType} onChange={e=>setF({...f,contactType:e.target.value as ContactType})}><option value="">미확인 / 나중에 입력</option>{contactTypes.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="번호 또는 SNS 아이디"><input className={field} value={f.contactValue} onChange={e=>setF({...f,contactValue:f.contactType==="번호"?formatPhone(e.target.value):e.target.value})}/></Label><Label text="상환일"><input type="date" className={field} value={f.dueDate} onChange={e=>setF({...f,dueDate:e.target.value})}/></Label><Label text="상환금액"><NumberInput value={f.status==="종결"?0:f.amount} disabled={f.status==="종결"} onChange={v=>setF({...f,amount:v})}/></Label><Label text="계좌/전달정보"><input className={field} value={f.account} onChange={e=>setF({...f,account:e.target.value})}/></Label><Label text="상태"><select className={field} value={f.status} onChange={e=>{const status=e.target.value as RepaymentStatus;setF({...f,status,amount:status==="종결"?0:f.amount})}}>{repaymentStatuses.map(x=><option key={x}>{x}</option>)}</select></Label><Label text="메모"><input className={field} value={f.memo} onChange={e=>setF({...f,memo:e.target.value})}/></Label><div className="sm:col-span-2 flex justify-end gap-2"><Button variant="secondary" onClick={onClose}>취소</Button><Button onClick={()=>{s.updateRepayment(repayment.id,f);onClose()}}>저장</Button></div></div></Modal>}
type SettlementDraft=Omit<Settlement,"id">;
const emptySettlement=():SettlementDraft=>({paidDate:today(),clientName:"",amount:0,paymentMethod:"계좌이체",memo:""});
function Settlements(){const s=useAdminStore();const def=monthRange();const [start,setStart]=useState(def.start);const [end,setEnd]=useState(def.end);const [appliedStart,setAppliedStart]=useState(def.start);const [appliedEnd,setAppliedEnd]=useState(def.end);const [page,setPage]=useState(1);const [settlePage,setSettlePage]=useState(1);const [open,setOpen]=useState(false);const [editing,setEditing]=useState<Settlement|null>(null);const [form,setForm]=useState<SettlementDraft>(emptySettlement());const [del,setDel]=useState<Settlement|null>(null);const baseContractEvents=s.customers.filter(c=>isEformSignedStatus(c.eformsignStatus)&&(c.isAccident?c.contractAmount:(c.baseContractAmount??c.contractAmount))>0).map(c=>({customerId:c.id,date:c.contractDate||c.createdAt,amount:c.isAccident?c.contractAmount:(c.baseContractAmount??c.contractAmount),kind:"최초계약" as const})).filter(x=>inRange(x.date,appliedStart,appliedEnd));const additionalContractEvents=s.additionalContracts.filter(x=>s.customers.some(c=>c.id===x.customerId&&isEformSignedStatus(c.eformsignStatus)&&!c.isAccident)&&x.contractAmount>0).map(x=>({customerId:x.customerId,date:x.contractDate||String(x.createdTime||"").slice(0,10),amount:x.contractAmount,kind:"추가계약" as const})).filter(x=>inRange(x.date,appliedStart,appliedEnd));const contractEvents=[...baseContractEvents,...additionalContractEvents];const paidInRange=s.payments.filter(p=>s.customers.some(c=>c.id===p.customerId&&isEformSignedStatus(c.eformsignStatus))&&p.paidDate&&p.paidAmount>0&&inRange(p.paidDate,appliedStart,appliedEnd)&&p.status!=="환불").sort((a,b)=>(b.paidDate||"").localeCompare(a.paidDate||"")||newestFirst(a,b));const contractPaidInRange=paidInRange.filter(p=>p.scheduleType!=="환수");const recoveryPaidInRange=paidInRange.filter(p=>p.scheduleType==="환수");const contractSales=contractEvents.reduce((sum,x)=>sum+x.amount,0);const contractRealSales=contractPaidInRange.reduce((a,b)=>a+b.paidAmount,0);const recoverySales=recoveryPaidInRange.reduce((a,b)=>a+b.paidAmount,0);const customerIds=new Set([...contractEvents.map(x=>x.customerId),...paidInRange.map(p=>p.customerId)]);const rows=s.customers.filter(c=>customerIds.has(c.id)).sort(newestFirst);const totalOutstanding=s.customers.filter(c=>isEformSignedStatus(c.eformsignStatus)).reduce((sum,c)=>sum+Math.max(0,c.contractAmount-customerPaid(s.payments,c.id)),0);const settlementRows=s.settlements.filter(x=>inRange(x.paidDate,appliedStart,appliedEnd)).sort((a,b)=>(b.paidDate||"").localeCompare(a.paidDate||"")||newestFirst(a,b));const settlementTotal=settlementRows.reduce((a,b)=>a+b.amount,0);const autoSettlementCount=settlementRows.filter(x=>x.entrySource==="payment").length;const manualSettlementCount=settlementRows.length-autoSettlementCount;function resetMonth(){setStart(def.start);setEnd(def.end);setAppliedStart(def.start);setAppliedEnd(def.end);setPage(1);setSettlePage(1)}function beginAdd(){setEditing(null);setForm(emptySettlement());setOpen(true)}function beginEdit(x:Settlement){setEditing(x);setForm({paidDate:x.paidDate,clientName:x.clientName,amount:x.amount,paymentMethod:x.paymentMethod,memo:x.memo});setOpen(true)}function saveSettlement(){editing?s.updateSettlement(editing.id,form):s.addSettlement(form);setOpen(false)}function settlementPhone(x:Settlement){const direct=x.customerId?s.customers.find(c=>c.id===x.customerId):undefined;if(direct)return direct.phone||"-";const source=x.sourcePaymentScheduleId?s.payments.find(p=>p.id===x.sourcePaymentScheduleId):undefined;const sourceCustomer=source?s.customers.find(c=>c.id===source.customerId):undefined;if(sourceCustomer)return sourceCustomer.phone||"-";const sameName=s.customers.filter(c=>c.name.trim()&&c.name.trim()===x.clientName.trim());return sameName.length===1?(sameName[0].phone||"-"):"-"}function csvCell(v:string|number){return `"${String(v??"").replaceAll('"','""')}"`}function downloadSettlement(){const header=["입금일시","의뢰인 성함","연락처","구분","연동","결제금액","결제 방법","비고"];const body=settlementRows.map(x=>[x.paidDate,x.clientName,settlementPhone(x),x.entryType||"계약",x.entrySource==="payment"?"자동":"수기",x.amount,x.paymentMethod,x.memo]);const csv="\uFEFF"+[header,...body].map(r=>r.map(csvCell).join(",")).join("\r\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`로펌_정산표_${appliedStart}_${appliedEnd}.csv`;a.click();URL.revokeObjectURL(url)}return <><PageHeader title="정산" description="운영 정산 현황을 확인합니다. 입금/분납에서 완료 처리된 실제 입금은 로펌 정산표에 자동 연동되며, 필요한 내역은 수기로도 추가할 수 있습니다."/><Card className="mb-4 p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end"><div><div className="mb-1.5 text-sm font-semibold">조회 기간</div><DateRangePicker start={start} end={end} onChange={(a,b)=>{setStart(a);setEnd(b);setAppliedStart(a);setAppliedEnd(b);setPage(1);setSettlePage(1)}}/></div><div className="flex gap-2"><Button variant="secondary" onClick={resetMonth}>이번달</Button></div></div></Card><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["계약 매출",contractSales],["실매출(계약건)",contractRealSales],["환수",recoverySales],["현재 미수금",totalOutstanding]].map(([l,v])=><Card key={l as string} className="p-5"><div className="text-sm text-slate-500">{l}</div><div className={`mt-2 text-2xl font-bold ${l==="현재 미수금"?"text-red-600":l==="환수"?"text-emerald-700":""}`}>{won(v as number)}</div></Card>)}</div>
<Card className="mt-4 overflow-hidden"><div className="flex flex-col gap-3 border-b border-slate-100 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="font-bold">로펌 정산표</div><div className="mt-1 text-xs text-slate-500">{appliedStart} ~ {appliedEnd} · 자동연동 {autoSettlementCount}건 · 수기 {manualSettlementCount}건</div></div><div className="flex flex-wrap items-center gap-2"><div className="rounded-lg bg-blue-50 px-4 py-2 text-sm font-bold text-blue-700">합계 {won(settlementTotal)}</div><Button variant="secondary" onClick={downloadSettlement}><Download size={15}/>CSV 다운로드</Button><Button onClick={beginAdd}><Plus size={15}/>정산 내역 추가</Button></div></div><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1100px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["입금일시","의뢰인 성함","연락처","구분","연동","결제금액","결제 방법","비고",""].map(h=><th className="px-4 py-3" key={h}>{h}</th>)}</tr></thead><tbody>{pageRows(settlementRows,settlePage,10).map(x=><tr key={x.id} className="border-t border-slate-100"><td className="px-4 py-3">{x.paidDate}</td><td className="px-4 py-3 font-semibold">{x.clientName}</td><td className="whitespace-nowrap px-4 py-3">{settlementPhone(x)}</td><td className="px-4 py-3">{x.entryType==="환수"?<Badge tone="green">환수</Badge>:<Badge tone="blue">계약</Badge>}</td><td className="px-4 py-3">{x.entrySource==="payment"?<Badge tone="green">자동연동</Badge>:<Badge tone="gray">수기</Badge>}</td><td className="px-4 py-3 font-semibold text-blue-700">{won(x.amount)}</td><td className="px-4 py-3">{x.paymentMethod}</td><td className="max-w-72 truncate px-4 py-3">{x.memo||"-"}</td><td className="px-4 py-3">{x.entrySource==="payment"?<div className="text-right"><Badge tone="gray">입금/분납에서 관리</Badge></div>:<div className="flex justify-end gap-1"><Button variant="secondary" onClick={()=>beginEdit(x)}>수정</Button><Button variant="danger" onClick={()=>setDel(x)}>삭제</Button></div>}</td></tr>)}{settlementRows.length===0&&<tr><td colSpan={9} className="px-4 py-10 text-center text-slate-400">선택한 기간에 로펌 정산 내역이 없습니다.</td></tr>}</tbody></table></div><Pagination page={settlePage} total={settlementRows.length} pageSize={10} onChange={setSettlePage}/></Card>
<Card className="mt-4 overflow-hidden"><div className="border-b border-slate-100 px-5 py-4"><div className="font-bold">기간별 고객 정산 현황</div><div className="mt-1 text-xs text-slate-500">최초 계약과 추가 계약을 각각의 계약일 기준으로 분리해 해당 기간에 발생한 계약매출만 표시합니다.</div></div><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1080px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["고객명","연락처","영업 담당자","조율 담당자","기간 계약매출","실매출(계약건)","환수","현재 미수금","상태"].map(h=><th className="px-4 py-3" key={h}>{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(c=>{const baseSales=baseContractEvents.filter(x=>x.customerId===c.id).reduce((sum,x)=>sum+x.amount,0);const additionalSales=additionalContractEvents.filter(x=>x.customerId===c.id).reduce((sum,x)=>sum+x.amount,0);const periodContractSales=baseSales+additionalSales;const periodContractPaid=contractPaidInRange.filter(p=>p.customerId===c.id).reduce((a,b)=>a+b.paidAmount,0);const periodRecovery=recoveryPaidInRange.filter(p=>p.customerId===c.id).reduce((a,b)=>a+b.paidAmount,0);const due=isEformSignedStatus(c.eformsignStatus)?Math.max(0,c.contractAmount-customerPaid(s.payments,c.id)):0;return <tr key={c.id} className="border-t border-slate-100"><td className="px-4 py-3 font-semibold">{c.name}</td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3"><div className="font-semibold text-blue-700">{won(periodContractSales)}</div>{periodContractSales>0&&<div className="mt-1 text-[11px] text-slate-400">{baseSales>0?`최초 ${won(baseSales)}`:""}{baseSales>0&&additionalSales>0?" + ":""}{additionalSales>0?`추가 ${won(additionalSales)}`:""}</div>}</td><td className="px-4 py-3 text-blue-700">{won(periodContractPaid)}</td><td className="px-4 py-3 text-emerald-700">{won(periodRecovery)}</td><td className="px-4 py-3 text-red-600">{won(due)}</td><td className="px-4 py-3"><Badge tone={due===0&&c.contractAmount>0?"green":"blue"}>{due===0&&c.contractAmount>0?"종결":"진행"}</Badge></td></tr>})}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card><Modal open={open} title={editing?"정산 내역 수정":"정산 내역 추가"} onClose={()=>setOpen(false)}><div className="grid gap-4 sm:grid-cols-2"><Label text="입금일시"><input type="date" className={field} value={form.paidDate} onChange={e=>setForm({...form,paidDate:e.target.value})}/></Label><Label text="의뢰인 성함"><input className={field} value={form.clientName} onChange={e=>setForm({...form,clientName:e.target.value})} placeholder="예: 홍길동"/></Label><Label text="결제금액"><NumberInput value={form.amount} onChange={v=>setForm({...form,amount:v})}/></Label><Label text="결제 방법"><select className={field} value={form.paymentMethod} onChange={e=>setForm({...form,paymentMethod:e.target.value})}>{paymentMethods.map(x=><option key={x}>{x}</option>)}</select></Label><div className="sm:col-span-2"><Label text="비고"><input className={field} value={form.memo} onChange={e=>setForm({...form,memo:e.target.value})} placeholder="예: 세금계산서 발행"/></Label></div><div className="sm:col-span-2 flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>취소</Button><Button onClick={saveSettlement}>저장</Button></div></div></Modal><ConfirmDelete open={!!del} name={del?`${del.clientName}님의 ${del.paidDate} 정산 내역`:"정산 내역"} label="로펌 정산 내역" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deleteSettlement(del.id)}}/></>}

const emptyLender=():Omit<Lender,"id">=>({createdAt:today(),name:"",contacts:[{id:`LC-${Date.now()}`,type:"번호",value:""}],account:"",memo:"",customerIds:[]});
function Lenders(){const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [open,setOpen]=useState(false);const [editing,setEditing]=useState<Lender|null>(null);const [form,setForm]=useState(emptyLender());const [del,setDel]=useState<Lender|null>(null);const [customerPickerOpen,setCustomerPickerOpen]=useState(false);const [customerQ,setCustomerQ]=useState("");const rows=useMemo(()=>s.lenders.filter(l=>`${l.name} ${l.contacts.map(c=>c.value).join(" ")} ${l.account} ${l.customerIds.map(id=>{const c=s.customers.find(x=>x.id===id);return `${c?.name||""} ${c?.phone||""}`}).join(" ")}`.toLowerCase().includes(q.toLowerCase())).sort(newestFirst),[s.lenders,s.customers,q]);const customerRows=useMemo(()=>s.customers.filter(c=>!form.customerIds.includes(c.id)&&`${c.name} ${c.phone}`.toLowerCase().includes(customerQ.toLowerCase())).sort(newestFirst),[s.customers,form.customerIds,customerQ]);function beginAdd(){setEditing(null);setForm(emptyLender());setCustomerQ("");setOpen(true)}function beginEdit(l:Lender){setEditing(l);setForm({...l,contacts:l.contacts.map(c=>({...c})),customerIds:[...l.customerIds]});setCustomerQ("");setOpen(true)}function save(){const clean={...form,contacts:form.contacts.map(c=>({...c,value:c.value||""}))};if(editing)s.updateLender(editing.id,clean);else s.addLender(clean);setOpen(false)}function addCustomer(id:string){if(!form.customerIds.includes(id))setForm({...form,customerIds:[...form.customerIds,id]})}return <><PageHeader title="사채업체 관리" description="업체 연락정보와 해당 업체를 이용한 의뢰인을 함께 관리합니다." action={<Button onClick={beginAdd}><Plus size={15}/>업체 등록</Button>}/><div className="mb-4 grid gap-3 sm:grid-cols-[220px_1fr]"><Card className="flex items-center justify-between px-4 py-3"><div><div className="text-xs font-semibold text-slate-500">총 등록 사채업체</div><div className="mt-1 text-2xl font-bold text-slate-900">{s.lenders.length.toLocaleString()}<span className="ml-1 text-sm font-semibold text-slate-500">개</span></div></div></Card><Card className="p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1)}} placeholder="업체명, 연락정보 또는 이용 의뢰인 검색"/></Card></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[850px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["등록일","업체명","이용 의뢰인","연락수단","연락정보","계좌번호","특이사항",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(l=><tr key={l.id} className="border-t border-slate-100"><td className="px-4 py-3">{l.createdAt}</td><td className="px-4 py-3 font-semibold">{l.name}</td><td className="px-4 py-3">{l.customerIds.map(id=>s.customers.find(c=>c.id===id)?.name).filter(Boolean).join(", ")||"-"}</td><td className="px-4 py-3">{l.contacts.map(c=>c.type).join(", ")}</td><td className="px-4 py-3">{l.contacts.map(c=>c.value).join(" / ")||"-"}</td><td className="px-4 py-3">{l.account||"-"}</td><td className="px-4 py-3">{l.memo||"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>beginEdit(l)}>수정</Button><Button variant="danger" onClick={()=>setDel(l)}>삭제</Button></div></td></tr>)}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card><Modal open={open} title={editing?"사채업체 수정":"사채업체 등록"} onClose={()=>setOpen(false)}><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Label text="등록일"><input type="date" className={field} value={form.createdAt} onChange={e=>setForm({...form,createdAt:e.target.value})}/></Label><Label text="업체명"><input className={field} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Label></div><div><div className="mb-2 flex items-center justify-between"><b className="text-sm">연락수단 / 계정</b><Button variant="secondary" onClick={()=>setForm({...form,contacts:[...form.contacts,{id:`LC-${Date.now()}-${form.contacts.length}`,type:"번호",value:""}]})}><Plus size={14}/>추가</Button></div><div className="space-y-2">{form.contacts.map(c=><div key={c.id} className="grid grid-cols-1 gap-2 sm:grid-cols-[130px_1fr_auto]"><select className={field} value={c.type} onChange={e=>setForm({...form,contacts:form.contacts.map(x=>x.id===c.id?{...x,type:e.target.value as ContactType}:x)})}>{contactTypes.map(x=><option key={x}>{x}</option>)}</select><input className={field} value={c.value} onChange={e=>setForm({...form,contacts:form.contacts.map(x=>x.id===c.id?{...x,value:e.target.value}:x)})} placeholder="번호 또는 SNS 아이디"/><Button variant="danger" onClick={()=>{if(form.contacts.length>1)setForm({...form,contacts:form.contacts.filter(x=>x.id!==c.id)})}}>삭제</Button></div>)}</div></div><div><div className="mb-1.5 flex items-center justify-between"><div className="text-sm font-semibold">이용 의뢰인</div><Button variant="secondary" onClick={()=>{setCustomerQ("");setCustomerPickerOpen(true)}}><UserRoundSearch size={15}/>의뢰인 검색</Button></div><div className="flex flex-wrap gap-2 rounded-xl border border-slate-200 bg-slate-50 p-3">{form.customerIds.map(id=>{const c=s.customers.find(x=>x.id===id);return c?<span key={id} className="inline-flex items-center gap-1 rounded-full bg-blue-50 px-2.5 py-1 text-xs font-semibold text-blue-700">{c.name} · {c.phone}<button type="button" className="ml-1 text-blue-400 hover:text-red-600" onClick={()=>setForm({...form,customerIds:form.customerIds.filter(x=>x!==id)})}>×</button></span>:null})}{form.customerIds.length===0&&<span className="text-xs text-slate-400">등록된 이용 의뢰인이 없습니다.</span>}</div></div><Label text="계좌번호"><input className={field} value={form.account} onChange={e=>setForm({...form,account:e.target.value})} placeholder="은행 / 계좌번호 / 예금주"/></Label><Label text="특이사항"><textarea className={textarea} value={form.memo} onChange={e=>setForm({...form,memo:e.target.value})}/></Label><div className="flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>취소</Button><Button onClick={save}>저장</Button></div></div></Modal><Modal open={customerPickerOpen} title="이용 의뢰인 검색" onClose={()=>setCustomerPickerOpen(false)}><div className="space-y-3"><SearchBox value={customerQ} onChange={setCustomerQ} onReset={()=>setCustomerQ("")} placeholder="고객명 또는 전화번호 검색"/><div className="max-h-[420px] overflow-auto rounded-xl border border-slate-200"><table className="admin-responsive-table w-full text-sm"><thead className="sticky top-0 bg-slate-50 text-left text-xs text-slate-500"><tr><th className="px-4 py-3">고객명</th><th className="px-4 py-3">연락처</th><th className="px-4 py-3">영업</th><th className="px-4 py-3"></th></tr></thead><tbody>{customerRows.map(c=><tr key={c.id} className="border-t border-slate-100"><td className="px-4 py-3 font-semibold">{c.name}</td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3 text-right"><Button onClick={()=>addCustomer(c.id)}>추가</Button></td></tr>)}{customerRows.length===0&&<tr><td colSpan={4} className="px-4 py-10 text-center text-slate-400">추가할 의뢰인이 없습니다.</td></tr>}</tbody></table></div><div className="flex justify-end"><Button variant="secondary" onClick={()=>setCustomerPickerOpen(false)}>완료</Button></div></div></Modal><ConfirmDelete open={!!del} name={del?.name||"업체"} label="사채업체 정보" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deleteLender(del.id)}}/></>}
function Board(){const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [open,setOpen]=useState(false);const [view,setView]=useState<string|null>(null);const [editing,setEditing]=useState<string|null>(null);const [del,setDel]=useState<string|null>(null);const empty=()=>({title:"",body:"",writer:"신홍규",date:today(),isNotice:false,noticeOrder:1,attachments:[] as Attachment[]});const [form,setForm]=useState(empty());const rows=useMemo(()=>s.posts.filter(p=>`${p.title} ${p.body} ${p.writer}`.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>a.isNotice!==b.isNotice?(a.isNotice?-1:1):a.isNotice?(a.noticeOrder-b.noticeOrder||newestFirst(a,b)):newestFirst(a,b)),[s.posts,q]);const viewing=s.posts.find(p=>p.id===view);function add(){setEditing(null);setForm(empty());setOpen(true)}function edit(p:BoardPost){setEditing(p.id);setForm({title:p.title,body:p.body,writer:p.writer,date:p.date,isNotice:p.isNotice,noticeOrder:p.noticeOrder,attachments:[...p.attachments]});setOpen(true)}async function files(fs:FileList|null){if(!fs)return;const next=[...form.attachments];for(const file of Array.from(fs)){const id=`F-${Date.now()}-${Math.random()}`;const storagePath=await saveFile(id,file);next.push({id,name:file.name,size:file.size,type:file.type,storagePath})}setForm({...form,attachments:next})}async function save(){editing?s.updatePost(editing,form):s.addPost(form);setOpen(false)}async function download(a:Attachment){const blob=await getFile(a.storagePath);if(!blob)return alert("첨부파일을 불러오지 못했습니다.");const url=URL.createObjectURL(blob);const x=document.createElement("a");x.href=url;x.download=a.name;x.click();URL.revokeObjectURL(url)}return <><PageHeader title="내부 게시판" description="공지 고정, 순서 설정, 본문 및 파일 첨부를 지원합니다." action={<Button onClick={add}><Plus size={15}/>글 생성</Button>}/><Card className="mb-4 p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1)}} placeholder="제목, 본문 또는 작성자 검색"/></Card><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[850px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["구분","제목","작성자","등록일","첨부",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(p=><tr key={p.id} className="border-t border-slate-100"><td className="px-4 py-3">{p.isNotice?<Badge tone="blue">공지 {p.noticeOrder}</Badge>:"일반"}</td><td className="px-4 py-3"><button className="font-semibold hover:text-blue-700" onClick={()=>setView(p.id)}>{p.title}</button></td><td className="px-4 py-3">{p.writer}</td><td className="px-4 py-3">{p.date}</td><td className="px-4 py-3">{p.attachments.length?`${p.attachments.length}개`:"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>edit(p)}>수정</Button><Button variant="danger" onClick={()=>setDel(p.id)}>삭제</Button></div></td></tr>)}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card><Modal open={open} title={editing?"게시글 수정":"게시글 생성"} onClose={()=>setOpen(false)}><div className="space-y-4"><Label text="제목"><input className={field} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Label><Label text="본문"><textarea className={`${textarea} min-h-48`} value={form.body} onChange={e=>setForm({...form,body:e.target.value})}/></Label><div className="grid gap-3 sm:grid-cols-2"><Label text="작성자"><input className={field} value={form.writer} onChange={e=>setForm({...form,writer:e.target.value})}/></Label><Label text="등록일"><input type="date" className={field} value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></Label></div><div className="flex items-center gap-3"><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={form.isNotice} onChange={e=>setForm({...form,isNotice:e.target.checked})}/>공지사항</label>{form.isNotice&&<NumberInput min={1} className="w-28" value={form.noticeOrder} onChange={v=>setForm({...form,noticeOrder:v})}/>}</div><div><label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold hover:bg-slate-50"><Paperclip size={15}/>파일 첨부<input type="file" multiple className="hidden" onChange={e=>files(e.target.files)}/></label><div className="mt-2 space-y-1">{form.attachments.map(a=><div key={a.id} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-xs"><span>{a.name} · {(a.size/1024/1024).toFixed(2)}MB</span><button className="text-red-600" onClick={async()=>{await deleteFile(a.storagePath);setForm({...form,attachments:form.attachments.filter(x=>x.id!==a.id)})}}>삭제</button></div>)}</div></div><div className="flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>취소</Button><Button onClick={save}>저장</Button></div></div></Modal><Modal open={!!viewing} title={viewing?.title||"게시글"} onClose={()=>setView(null)}>{viewing&&<div><div className="mb-4 flex gap-3 text-xs text-slate-400"><span>{viewing.writer}</span><span>{viewing.date}</span>{viewing.isNotice&&<Badge tone="blue">공지</Badge>}</div><div className="whitespace-pre-wrap text-sm leading-7">{viewing.body}</div>{viewing.attachments.length>0&&<div className="mt-5 border-t border-slate-100 pt-4"><b className="text-sm">첨부파일</b><div className="mt-2 space-y-2">{viewing.attachments.map(a=><button key={a.id} onClick={()=>download(a)} className="flex w-full items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-sm hover:bg-blue-50"><span>{a.name}</span><Download size={15}/></button>)}</div></div>}</div>}</Modal><ConfirmDelete open={!!del} name={s.posts.find(p=>p.id===del)?.title||"게시글"} label="게시글" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deletePost(del)}}/></>}
